const req = $input.first().json || {};
const headers = req.headers || {};
const body = req.body || {};
const query = req.query || {};

// 1. Extract Token from Authorization header (Bearer <token>) or body/query
let rawHeader = headers['authorization'] || headers['Authorization'] || '';
let token = '';

if (typeof rawHeader === 'string' && rawHeader.toLowerCase().startsWith('bearer ')) {
  token = rawHeader.substring(7).trim();
} else if (typeof rawHeader === 'string' && rawHeader.trim().length > 0 && !rawHeader.includes(' ')) {
  token = rawHeader.trim();
} else if (body.token) {
  token = String(body.token).trim();
} else if (query.token) {
  token = String(query.token).trim();
}

if (!token) {
  return [{
    json: {
      hasToken: false,
      statusCode: 401,
      error: "Access denied. Authentication token required. Outsiders are not permitted."
    }
  }];
}

return [{
  json: {
    hasToken: true,
    token: token
  }
}];

const inputData = $input.first().json || {};

if (inputData.error) {
  return [{
    json: {
      authorized: false,
      statusCode: 401,
      error: "Invalid or expired authentication token. Outsiders are not permitted."
    }
  }];
}

const claims = inputData.payload || inputData;

if (!claims || !claims.sub) {
  return [{
    json: {
      authorized: false,
      statusCode: 401,
      error: "Invalid or malformed authentication token. Outsiders are not permitted. Please log in again."
    }
  }];
}

const authUserId = String(claims.sub).trim();
const authUserRole = String(claims.role || 'EMPLOYEE').toUpperCase();
const authUserName = claims.name || authUserId;

const webhookNode = $('Webhook - POST /overtime-list').first().json || {};
const webhookBody = webhookNode.body || {};
const action = (webhookBody.action || 'LIST').toUpperCase().trim();
const requestedId = (webhookBody.employeeId || webhookBody.email || '').trim();

if (action === 'APPROVE' || action === 'REJECT') {
  // Only ADMIN can approve or reject overtime records
  if (authUserRole !== 'ADMIN') {
    return [{
      json: {
        authorized: false,
        statusCode: 403,
        error: "Forbidden: Only Administrators can approve or reject overtime requests."
      }
    }];
  }

  const overtimeId = String(webhookBody.overtimeId || '').trim();
  if (!overtimeId) {
    return [{
      json: {
        authorized: false,
        statusCode: 400,
        error: "Missing required field: overtimeId is required for approval/rejection."
      }
    }];
  }

  return [{
    json: {
      authorized: true,
      action: action,
      overtimeId: overtimeId,
      approverName: authUserName,
      adminNotes: webhookBody.notes || (action === 'APPROVE' ? 'Approved for weekly early-leave adjustment' : 'Rejected by Admin'),
      authUser: { id: authUserId, role: authUserRole }
    }
  }];
}

// Default action: LIST
let targetEmployeeId = authUserId;
if (requestedId) {
  const isSelf = (requestedId === authUserId);
  if (isSelf) {
    targetEmployeeId = authUserId;
  } else if (authUserRole === 'ADMIN') {
    targetEmployeeId = requestedId;
  } else {
    return [{
      json: {
        authorized: false,
        statusCode: 403,
        error: "Forbidden: You are not authorized to view another employee's overtime records."
      }
    }];
  }
}

return [{
  json: {
    authorized: true,
    action: 'LIST',
    targetEmployeeId: targetEmployeeId,
    authUser: { id: authUserId, role: authUserRole }
  }
}];

const items = $input.all();
const data = (items.length > 0 && items[0].json) ? items[0].json : {};

if (!data.employee_found || !data.employee) {
  return [{
    json: {
      success: false,
      statusCode: 404,
      error: "Employee not found in database."
    }
  }];
}

const sm = data.summary || {};
let records = [];
try {
  records = typeof data.records === 'string' 
    ? JSON.parse(data.records) 
    : (Array.isArray(data.records) ? data.records : []);
} catch (e) {
  records = [];
}

return [{
  json: {
    success: true,
    statusCode: 200,
    employee: data.employee,
    summary: {
      totalApprovedHours: `${parseFloat(sm.approved_hours || '0.0').toFixed(1)}h`,
      totalPendingHours: `${parseFloat(sm.pending_hours || '0.0').toFixed(1)}h`,
      earlyLeaveHoursAvailable: `${parseFloat(sm.available_early_leave_hours || '0.0').toFixed(1)}h`,
      earlyLeaveMinutesAvailable: parseInt(sm.available_early_leave_minutes || '0', 10),
      reimbursementPendingCount: parseInt(sm.reimbursement_pending_count || '0', 10),
      pendingApprovalsCount: parseInt(sm.pending_count || '0', 10)
    },
    records: records
  }
}];

const items = $input.all();
const data = (items.length > 0 && items[0].json) ? items[0].json : {};
const routerData = $('Code - Enforce RBAC & Resolve Overtime Action').first().json || {};

if (!data.id) {
  return [{
    json: {
      success: false,
      statusCode: 404,
      error: `Overtime record ${routerData.overtimeId} not found.`
    }
  }];
}

const actionVerb = routerData.action === 'APPROVE' ? 'approved' : 'rejected';

return [{
  json: {
    success: true,
    statusCode: 200,
    message: `Overtime record ${data.id} has been ${actionVerb} successfully.`,
    action: routerData.action,
    record: {
      id: data.id,
      employeeId: data.employee_id,
      date: data.date,
      startTime: data.start_time,
      endTime: data.end_time,
      durationMinutes: data.duration_minutes,
      hoursFormatted: data.hours_formatted,
      status: data.status,
      earlyLeaveStatus: data.early_leave_status,
      approver: data.approver,
      reviewedDate: data.reviewed_date,
      notes: data.notes
    }
  }
}];

